"""One real-template Host-file DAX lifecycle, on the already deployed A Runtime.

No original service changes, SDK, UB allocation, kernel changes or cache drops.
Retains the new snapshot and logs. Unknown POST outcomes are never retried.
"""
import argparse,base64,copy,hashlib,json,os,re,shutil,signal,socket,stat,subprocess,sys,time,types,uuid
from pathlib import Path
ROOT=Path('/home/jwk/agent')
D=ROOT/'deployments/agentenv-dsec-hostfile-v1'
WORK=D/'dsec-real-template-smoke-v1'
UNIT='jwk-aenv-dsec-hostfile-v1-node-a.service'
CORE='eb2301e7bd924784287f6c50d4faa4cabc7ca52b'
PREPARE_SHA='d17183de4707cc4631eb6692cbd6e8bce00a995174cc571b37ac8c3d6ba049cd'
PAYLOAD={'four_runtime': {'sha256': 'f4b31e6dbee970d757d8c5eaddd9b0d679c0ad6e512fffdc32c7a3115975f687', 'b64': ''}, 'cohort_engine': {'sha256': '5d0cd8d4cf45b8301532517af832710c3928458f20c1cc64b0991500ddb1b89d', 'b64': ''}, 'four_replay': {'sha256': '780779b6d3f2c6ea2b7c4a6115d193b9d4116b654251149bac1cc5e0d004d20e', 'b64': ''}}

def need(value,reason):
    if not value:raise RuntimeError(reason)

def module(name):
    row=PAYLOAD[name];raw=base64.b64decode(row['b64'],validate=True)
    need(hashlib.sha256(raw).hexdigest()==row['sha256'],'Embedded helper differs')
    value=types.ModuleType(name);value.__file__='<pinned-'+name+'>'
    exec(compile(raw,value.__file__,'exec'),value.__dict__)
    return value

def exercise(case,image,execute):
    """One cold parent; snapshot upper state; two independent concurrent restores."""
    parent=case.create('/sandboxes-cold',{'image':image['ociReference'],'cpuCount':2,'memoryMB':4096,
        'secure':True,'autoPause':False,'allowInternetAccess':False,'timeout':1800,
        'metadata':{'cow_batch':case.run_id}})
    execute(parent,'parent-prepare', 'parent')
    captured=case.capture(parent)
    case.delete(parent)
    children=[]
    for slot in range(2):
        children.append(case.create('/v2/sandboxes',{'templateID':captured,'timeout':1800,
            'secure':True,'autoPause':False,'allow_internet_access':False,
            'metadata':{'cow_batch':case.run_id,'dsec_slot':str(slot)}}))
    for slot,sid in enumerate(children):execute(sid,'restored-'+str(slot),'check')
    execute(children[0],'private-copy-up','write')
    execute(children[1],'peer-remains-original','check')
    execute(children[0],'writer-keeps-private-value','private')
    return {'snapshotId':captured,'children':children,'upperSnapshotRestorePassed':True,
            'privateCopyUpIsolationPassed':True,'explicitDaxAndInstructionProbesPassed':True,
            'scope':'single-node real-template functional lifecycle, not workload or savings comparison'}

def guest_action(run_id,mode):
    need(re.fullmatch('[0-9a-f]{32}',run_id) is not None,'Invalid run identity')
    need(mode in ('parent','check','write','private'),'Unknown Guest action')
    marker='/aenv-dsec-smoke-'+run_id
    common="set -eu; B=/agentenv/bin/busybox; test -x /agentenv/dax-check; test \"$($B id -u)\" -eq 0 || { echo DSEC_CHECK_REQUIRES_GUEST_ROOT >&2; exit 125; }; "
    dax="/agentenv/dax-check /.aenv-dax-exec; set +e; /.aenv-dax-exec; r=$?; set -e; test \"$r\" -eq 73; "
    original="test \"$($B cat /.aenv-dax-probe)\" = aenv-native-dax-v3; /agentenv/dax-check /.aenv-dax-probe; "
    if mode=='parent':
        return common+dax+original+'test ! -e '+marker+'; printf %s parent-'+run_id+' > '+marker+'; $B sync; printf DSEC_PARENT_OK'
    if mode=='check':
        return common+dax+original+'test "$( $B cat '+marker+' )" = parent-'+run_id+'; printf DSEC_RESTORE_OK'
    if mode=='write':
        return common+'printf %s private-'+run_id+' > /.aenv-dax-probe; printf %s child-'+run_id+' > '+marker+'; $B sync; printf DSEC_PRIVATE_WRITE_OK'
    return common+dax+'test "$( $B cat /.aenv-dax-probe )" = private-'+run_id+'; test "$( $B cat '+marker+' )" = child-'+run_id+'; printf DSEC_PRIVATE_READ_OK'

class Run:
    def __init__(self,recovery=False):
        self.rt=module('four_runtime');self.engine=module('cohort_engine');self.replay=module('four_replay')
        need(hashlib.sha256(self.rt.read(D/'libexec/native_prepare.py',512*1024)).hexdigest()==PREPARE_SHA,
             'Use the deployed v2 Host-file preparation')
        self.definition=self.rt.load(D/'definition-native.json');installation=self.rt.load(D/'installation.json')
        need(installation.get('commit')==CORE and installation.get('node')=='node-a','Installed core differs')
        self.api=self.rt.Api(D,UNIT,self.definition['apiPort'])
        need(self.api.pid==1880294 and self.api.ticks=='52944913' and self.api.port==18084,
             'Runtime changed since the returned healthy deployment; preserve it')
        need(self.api.call('GET','/health')[0]==204,'New Runtime unhealthy')
        for name,pin in installation['binaries'].items():
            need(self.rt.digest_file(D/'bin'/name)==pin,'Installed binary differs: '+name)
        binding=self.definition['rootfsBinding'];raw=self.rt.read(binding['path'])
        need(hashlib.sha256(raw).hexdigest()==binding['sha256'],'Binding catalog differs')
        self.bind=json.loads(raw)['bindings'][0]
        need('sha256:'+self.rt.digest_file(D/'deps/firecracker/1.15.1-patch-v3/firecracker')
             ==self.bind['deviceRuntime']['firecrackerSha256'],'Installed Firecracker differs')
        seed=self.rt.load(D/'rootfs-inputs.json');self.image=seed['images'][0]
        need(self.bind['version']==5 and self.bind['sourceImage']==self.image['sourceImage']
             and self.image['resources']['cpu_count']==2 and self.image['resources']['memory_mib']==4096,
             'First real template or Host-file v5 binding differs')
        self.base=ROOT/'builds/native-four-inputs-v1/case-0/raw/rootfs.ext4'
        self.context={'unit':UNIT,'pid':self.api.pid,'ticks':self.api.ticks,'configSha256':self.api.config_sha,
                      'bootId':Path('/proc/sys/kernel/random/boot_id').read_text().strip()}
        self.case=None;self.commands=[]
        self.env={'HOME':'/home/jwk','USER':'jwk','LOGNAME':'jwk','LANG':'C.UTF-8',
            'PATH':str(D/'native/bin')+':/usr/bin:/bin',
            'LD_LIBRARY_PATH':str(D/'native/lib')+':'+str(D/'native/fallback/lib'),
            'XDG_CONFIG_HOME':str(D/'cli/config'),'XDG_CACHE_HOME':str(D/'cli/cache'),
            'TMPDIR':str(D/'cli/tmp'),'NO_PROXY':'127.0.0.1,localhost,::1'}
        if recovery:
            state=self.rt.load(WORK/'state.json')
            need(state.get('runtimeContext')==self.context,'Recovery Runtime context differs')
            self.case=self.engine.Cohort.recovery(self.api,state,self.persist)
        else:
            state=self.rt.load(D/'cohort-state.json')
            need(self.engine.quiescent(state),'Existing cohort active or uncertain')
            need(self.api.call('GET','/v2/sandboxes?limit=1')==(200,[]),'New Runtime inventory not empty')
            need(not WORK.exists() and not WORK.is_symlink(),'Existing smoke preserved; use recover mode')
            WORK.mkdir(mode=0o700);(WORK/'commands').mkdir(mode=0o700)
            self.case=self.engine.Cohort(self.api,{'version':1,'phase':'prepared','openRequests':[],
                'sandboxIds':[],'outcomeUncertain':False,'runtimeContext':self.context},self.persist,
                None,None,self.capacity,self.snapshot)
        original_call=self.api.call
        def recorded_call(method,path,body=None,timeout=30):
            status,reply=original_call(method,path,body,timeout)
            if status>=400 and status!=404:
                details={k:reply[k] for k in ('message','error','detail','code') if k in reply} if isinstance(reply,dict) else {'error':str(reply)[:2000]}
                text=json.dumps(details).replace(self.api.key,'<redacted>')
                text=re.sub(r'e2b_[A-Za-z0-9._~-]+','<redacted>',text)
                with (WORK/'api-errors.jsonl').open('a') as log:
                    log.write(json.dumps({'method':method,'path':path,'status':status,'details':text[:3000]})+'\n')
            return status,reply
        self.api.call=recorded_call

    def persist(self,state):
        self.rt.save(WORK/'state.json',state)
        self.rt.save(D/'cohort-state.json',{'version':1,'phase':state['phase'],
            'openRequests':copy.deepcopy(state['openRequests']),'sandboxIds':list(state['sandboxIds']),
            'outcomeUncertain':bool(state['openRequests']),'dsecSmokeRunId':state['runId']})

    def capacity(self,kind):
        limit=int(Path('/sys/module/ublk_drv/parameters/ublks_max').read_text())
        count=sum(bool(re.fullmatch(r'ublkc\d+',p.name)) for p in Path('/sys/class/ublk-char').iterdir())
        needed=3 if kind=='cold' else 4
        need(0<limit<=4096 and limit-count>=needed,'Insufficient free ublk slots; existing devices preserved')
        info=dict(x.split(':',1) for x in Path('/proc/meminfo').read_text().splitlines())
        need(int(info['MemAvailable'].split()[0])*1024>=16*1024**3,'Need 16GiB available for bounded two-Guest test')
        need(shutil.disk_usage(ROOT).free>=16*1024**3,'Need 16GiB free disk; existing files preserved')

    def snapshot(self,sid):
        need(str(uuid.UUID(sid))==sid,'Snapshot ID is not canonical UUID')
        repo=D/'state/snapshot-store/repository'
        record_raw=self.rt.read(repo/'catalog/records'/(sid+'.json'))
        record=json.loads(record_raw)
        saved=self.rt.load(repo/'snapshots'/sid/'firecracker-manifest.json')
        expected={'version':1,'sourceImage':self.bind['sourceImage'],'filesystem':'ext4',
                  'layers':[{'sha256':x['sha256'],'bytes':x['bytes']} for x in self.bind['layers']]}
        need(record.get('id')==sid and saved.get('nativeRootfs')==expected and
             saved.get('memory',{}).get('virtualSize')==4096*1024**2,'Snapshot lacks exact native content or RAM geometry')
        return {'snapshotId':sid,'nativeRootfs':expected,'committedRecordSha256':hashlib.sha256(record_raw).hexdigest(),
                'externalBaseRetained':True,'selfContainedArchiveTested':False}

    def command(self,sid,label,mode):
        print('PHASE='+label,flush=True)
        need(self.case.owned(sid) is not None,'Owned Guest disappeared')
        marker='DSEC_SMOKE_END_'+uuid.uuid4().hex
        command=self.replay.shell_command(guest_action(self.case.run_id,mode),marker)
        outpath=WORK/'commands'/(label+'.stdout');errpath=WORK/'commands'/(label+'.stderr')
        started=time.monotonic();child=None
        try:
            with outpath.open('xb') as out,errpath.open('xb') as err:
                child=subprocess.Popen([str(D/'bin/aenv'),'exec',sid,'/bin/bash','-c',command],
                    stdin=subprocess.DEVNULL,stdout=out,stderr=err,env=self.env)
                while child.poll() is None:
                    need(time.monotonic()-started<330,'CLI command exceeded 330 seconds')
                    need(outpath.stat().st_size+errpath.stat().st_size<=4*1024**2,'Command output budget exceeded')
                    time.sleep(.2)
            need(child.returncode==0,'CLI transport failed; inspect private command logs')
            need(outpath.stat().st_size+errpath.stat().st_size<=4*1024**2,'Completed command output budget exceeded')
            text=outpath.read_text(errors='replace')
            matches=re.findall(r'(?m)^'+marker+r' ([0-9]+)\s*$',text)
            need(len(matches)==1 and matches[0]=='0','Guest check failed; inspect private command logs')
            if mode in ('parent','check'):need(text.count('DAX_ACTIVE ')>=2,'Explicit Guest DAX evidence missing')
            row={'label':label,'sandboxId':sid,'seconds':time.monotonic()-started,'exitCode':0,
                 'stdout':str(outpath),'stderr':str(errpath)}
            self.commands.append(row);self.rt.save(WORK/'commands.json',self.commands)
            return row
        finally:
            if child is not None and child.poll() is None:
                child.terminate()
                try:child.wait(timeout=5)
                except subprocess.TimeoutExpired:child.kill();child.wait(timeout=5)

    def base_digest(self):
        need(self.base.resolve(strict=True)==self.base,'Redirected base image')
        with self.base.open('rb') as stream:
            before=os.fstat(stream.fileno())
            need(stat.S_ISREG(before.st_mode) and before.st_uid==1204 and before.st_size==self.bind['layers'][0]['bytes'],
                 'Base file metadata differs')
            value=hashlib.file_digest(stream,'sha256').hexdigest();after=os.fstat(stream.fileno())
        identity=lambda s:(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns,s.st_ctime_ns)
        need(identity(before)==identity(after)==identity(self.base.stat()),'Base changed during verification')
        need('sha256:'+value==self.bind['layers'][0]['sha256'],'Base content changed')
        return {'identity':identity(after),'sha256':'sha256:'+value,'hashWarmsHostCache':True}

    def run(self,recovery):
        report={'status':'RUNNING','coreCommit':CORE,'runtimeContext':self.context,'SDK_called':False,
            'crossNodeMemfileCowAccepted':False,'globalPhysicalSavingBytes':None,'workDirectory':str(WORK),
            'sameWorkloadComparisonExecuted':False,'recoveryOnly':recovery}
        try:
            if recovery:
                self.case.recover_owned()
            else:
                print('PHASE=verify-retained-base-before',flush=True);before=self.base_digest()
                report['functional']=exercise(self.case,self.image,self.command)
                print('PHASE=verify-retained-base-after',flush=True);after=self.base_digest()
                need(before==after,'Host base identity changed during Guest operations')
                report['baseUnchanged']=True
                self.case.state['lifecyclePassed']=True;self.case.save()
        except (Exception,KeyboardInterrupt) as error:
            reason=str(error) if isinstance(error,RuntimeError) else 'Inspect preserved operation and command logs'
            reason=reason.replace(self.api.key,'<redacted>')
            report['error']={'type':type(error).__name__,'reason':re.sub(r'e2b_[A-Za-z0-9._~-]+','<redacted>',reason)[:1000]}
        finally:
            print('PHASE=owned-guest-cleanup-preserve-capture',flush=True)
            try:self.case.cleanup()
            except Exception as error:
                report['cleanupError']={'type':type(error).__name__,'reason':'Inspect preserved journal; no blind retry'}
            report['journal']=self.case.state;report['commands']=self.commands
            report['ownedGuestsReleased']='cleanupError' not in report and self.engine.quiescent(self.case.state)
            report['newSnapshotRetained']=list(self.case.state['snapshots'])
            if report['ownedGuestsReleased'] and 'error' not in report:
                report['status']='DSEC_OWNED_SMOKE_RECOVERY_COMPLETED' if recovery else 'DSEC_REAL_TEMPLATE_RESTORE_PAIR_PASSED_GUESTS_RELEASED'
            else:report['status']='STOPPED_DSEC_REAL_TEMPLATE_SMOKE_PRESERVE_JOURNAL'
            self.rt.save(WORK/('recovery-return.json' if recovery else 'return.json'),report)
            print('BEGIN_DSEC_REAL_TEMPLATE_SMOKE_REPORT');print(json.dumps(report,indent=2));print('END_DSEC_REAL_TEMPLATE_SMOKE_REPORT')
        return 0 if report['status'].startswith(('DSEC_REAL_TEMPLATE_RESTORE_PAIR_PASSED','DSEC_OWNED_SMOKE_RECOVERY_COMPLETED')) else 1

def main():
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('mode',choices=('plan','run','recover'),nargs='?',default='plan')
    args=parser.parse_args()
    if args.mode=='plan':
        print(json.dumps({'status':'PLAN_ONLY','maxSimultaneousGuests':2,'maxNewGuests':3,
            'newSnapshotLimit':1,'templateIndex':0,'GuestMemoryMiB':4096,'SDK_called':False}));return 0
    need(sys.platform=='linux' and os.uname().machine=='aarch64' and socket.gethostname()=='server1','Use A ARM64')
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk')
    caps=dict(x.split(':',1) for x in Path('/proc/self/status').read_text().splitlines() if ':' in x)
    need(all(int(caps[x],16)==0 for x in ('CapInh','CapPrm','CapEff','CapAmb')),'Capability-free caller required')
    import fcntl
    lock=os.open(D/'cohort.lock',os.O_RDWR|os.O_NOFOLLOW|os.O_CLOEXEC)
    try:
        meta=os.fstat(lock);need(stat.S_ISREG(meta.st_mode) and meta.st_uid==1204,'Unexpected cohort lock')
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB);os.umask(0o077)
        def cancelled(*_):raise KeyboardInterrupt('Operator interrupted')
        for name in ('SIGTERM','SIGHUP'):signal.signal(getattr(signal,name),cancelled)
        return Run(args.mode=='recover').run(args.mode=='recover')
    finally:os.close(lock)

if __name__=='__main__':
    try:raise SystemExit(main())
    except Exception as error:
        print(json.dumps({'status':'STOPPED_DSEC_SMOKE_ENTRY_PRESERVE_JOURNAL','errorType':type(error).__name__,
            'reason':re.sub(r'e2b_[A-Za-z0-9._~-]+','<redacted>',str(error))[:1000],
            'workDirectory':str(WORK),'automaticRetry':False}));raise SystemExit(1)
